const body = $input.first().json.body;

// Priorizar siempre @s.whatsapp.net sobre @lid
const remoteJid = body?.data?.key?.remoteJid || '';
const remoteJidAlt = body?.data?.key?.remoteJidAlt || '';
const sender = body?.sender || '';

let phoneRaw;
if (remoteJid.endsWith('@s.whatsapp.net')) {
  phoneRaw = remoteJid;
} else if (remoteJidAlt.endsWith('@s.whatsapp.net')) {
  phoneRaw = remoteJidAlt;
} else if (sender.endsWith('@s.whatsapp.net')) {
  phoneRaw = sender;
} else {
  phoneRaw = remoteJid; // fallback
}

const phone = phoneRaw.replace('@s.whatsapp.net', '');
const message = body?.data?.message?.conversation 
  || body?.data?.message?.extendedTextMessage?.text 
  || '';

return [{ json: { phone, message } }];

const extracted = $('Extraer datos del mensaje').first().json;
const sessionRows = $('Leer sesion Postgres').all();
const session = sessionRows[0]?.json || {};

const clientRows = $('Leer cliente Postgres').all();
const client = clientRows[0]?.json || {};

return [{
  json: {
    phone: extracted.phone,
    message: extracted.message,
    state: session.state ?? 'null',
    sessionData: session.data ?? {},
    client_id: client.client_id ?? null,
    client_negocio: client.client_negocio ?? null,
    productos_disponibles: client.productos_disponibles ?? []
  }
}];

const agentOutput = $input.first().json.output || '';
const phone = $('Preparar contexto').first().json.phone;
const existingData = $('Preparar contexto').first().json.sessionData || {};

let parsed;
try {
  const clean = agentOutput.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {};
}

const merged = {
  negocio: parsed.negocio || existingData.negocio || null,
  productos: (parsed.productos && parsed.productos.length > 0)
    ? parsed.productos
    : (existingData.productos || []),
  facturacion: parsed.facturacion || existingData.facturacion || null,
  horario: parsed.horario || existingData.horario || null
};

const faltante = [];
if (!merged.negocio) {
  faltante.push('el nombre de tu negocio o sucursal');
}
if (!merged.productos || merged.productos.length === 0) {
  faltante.push('los productos que necesitas con sus cantidades');
} else {
  const sinCantidad = merged.productos.filter(p => !p.cantidad || p.cantidad <= 0);
  if (sinCantidad.length > 0) {
    faltante.push('la cantidad de: ' + sinCantidad.map(p => p.nombre).join(', '));
  }
}

const completo = faltante.length === 0;

// Armar mensaje para el cliente
let mensaje;
if (completo) {
  const lineasProductos = merged.productos.map(p => `  • ${p.nombre} x${p.cantidad}`).join('\n');
  mensaje = `Esto es lo que tengo hasta ahora:\n\n🏪 Negocio: ${merged.negocio}\n\n📦 Productos:\n${lineasProductos}`;
  if (merged.facturacion) mensaje += `\n\n🧾 Facturación: ${merged.facturacion}`;
  if (merged.horario) mensaje += `\n\n🕐 Horario: ${merged.horario}`;
  mensaje += '\n\n¿Confirmás el pedido?\nRespondé *Si* para confirmar o *No* para cancelar.';
} else {
  const lineasProductos = merged.productos.length > 0
    ? '✅ Productos: ' + merged.productos.map(p => `${p.nombre} x${p.cantidad}`).join(', ')
    : '❌ Productos: pendiente';
  mensaje = `Esto es lo que tengo hasta ahora:\n\n${merged.negocio ? '✅ Negocio: ' + merged.negocio : '❌ Negocio: pendiente'}\n${lineasProductos}\n\nFalta que me indiques: ${faltante.join(' y ')}`;
}

return [{
  json: {
    phone,
    completo,
    falta: faltante.length > 0 ? faltante.join(' y ') : null,
    mensaje,
    data: merged
  }
}];

const ctx = $('Preparar contexto').first().json;
const message = ctx.message || '';
const normalized = message.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

return [{
  json: {
    respuesta: normalized,
    phone: ctx.phone,
    sessionData: ctx.sessionData
  }
}];

const ctx = $('Preparar contexto').first().json;
const intencion = $input.first().json.output;

let ruta;

if (ctx.state === 'esperando_pedido') {
  ruta = 'agente';
} else if (ctx.state === 'esperando_confirmacion') {
  ruta = 'confirmacion';
} else if (intencion === 'pedido') {
  ruta = 'agente';
} else {
  ruta = 'bienvenida';
}

return [{
  json: {
    phone: ctx.phone,
    message: ctx.message,
    state: ctx.state,
    sessionData: ctx.sessionData,
    intencion: intencion,
    ruta: ruta
  }
}];

