const sessionData = $('Preparar contexto').first().json.sessionData;
const phone = $('Preparar contexto').first().json.phone;
const client_id = $('Preparar contexto').first().json.client_id;

const matchingClienteOutput = $('Matching cliente').first().json.output;
let matchingCliente = {};
try {
  const clean = matchingClienteOutput.replace(/```json|```/g, '').trim();
  matchingCliente = JSON.parse(clean);
} catch(e) {}

const matchingProductosOutput = $('Matching productos').first().json.output;
let matchingProductos = { productos: [] };
try {
  const clean = matchingProductosOutput.replace(/```json|```/g, '').trim();
  matchingProductos = JSON.parse(clean);
} catch(e) {}

let total = 0;
const items = matchingProductos.productos.map(p => {
  const precio = p.precio_cliente || 0;
  const subtotal = precio * (p.cantidad || 0);
  total += subtotal;
  return {
    nombre_pedido: p.nombre_pedido,
    nombre_catalogo: p.nombre_catalogo,
    product_id: p.product_id ?? null,
    codigo_prod: p.codigo_prod ?? null,
    cantidad: p.cantidad,
    precio_unitario: precio,
    subtotal
  };
});

return [{
  json: {
    phone,
    client_id: client_id || matchingCliente.client_id || null,
    negocio: matchingCliente.negocio || sessionData.negocio,
    items,
    total,
    facturacion: sessionData.facturacion || null,
    horario: sessionData.horario || null,
    raw_data: sessionData
  }
}];
